  create policy "Enable read access for all users"
  on "public"."messages"
  as permissive
  for select
  to public
using (true);



  create policy "Enable read access for all users"
  on "public"."profiles"
  as permissive
  for select
  to public
using (true);



  create policy "Enable update for users based on user_uuid"
  on "public"."profiles"
  as permissive
  for update
  to public
using ((auth.uid() = user_uuid))
with check ((auth.uid() = user_uuid));


CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();


